  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C06", "C09", "C16", "C11", "C21", "C10"],
  "claims": [
    {
      "claim": "Codeine, the closest morphinan analog in the evidence set, has an absolute oral bioavailability of 80.5% in healthy subjects; hydromorphone shares the morphinan scaffold, 4,5-epoxy bridge, N-methyl group, and phenolic C3 substitution, supporting F ≥ 20%.",
      "card_ids": ["C06"]
    },
    {
      "claim": "Other opioid analgesics in the evidence set had oral bioavailability values above the 20% threshold: pentazocine ~0.68–0.70, meperidine 0.80, and meptazinol 27.9% in cirrhosis.",
      "card_ids": ["C09", "C16", "C11", "C21", "C10"]
    },
    {
      "claim": "No supplied record provides affirmative evidence of F < 20% for hydromorphone or a close analog; all relevant opioid F values exceed 20%.",
      "card_ids": ["C06", "C09", "C16", "C11", "C21", "C10"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "current_gold_voting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C06", "C09", "C16", "C11", "C21", "C10"]
    }
  ],
  "evidence_gaps": [
    "No direct hydromorphone absolute oral bioavailability record is present in the supplied cards; the prediction relies on structural and pharmacological class transfer.",
    "No matched oral-versus-intravenous hydromorphone exposure data in healthy subjects or a relevant disease population is available.",
    "Codeine differs from hydromorphone at C3 (methoxy vs phenol) and C6 (hydroxy vs ketone), which may alter first-pass metabolism.",
    "Several supporting opioid values were measured in cirrhosis patients and may not exactly reflect healthy-subject bioavailability, though all remain above 20%."
  ],
  "decision_summary": "Hydromorphone is predicted high (F ≥ 20%) based on the high oral bioavailability of the closest morphinan analog codeine (80.5%) and other opioids (pentazocine, meperidine, meptazinol all >20%), consistent with a favorable physicochemical prior; no evidence supports F < 20%, though no direct hydromorphone record is available."
}

